CREATE OR REPLACE VIEW business.policy360 AS SELECT p.policy_id,p.customer_id,p.region_id,p.current_agent_id,p.policy_type_code,p.status,p.premium_amount,p.sum_assured,p.total_premium_paid,p.total_premium_payable,p.payment_gap_months,p.purchase_date,r.region_name,r.region_dir,a.specialisation,a.performance_rating FROM core.policy p LEFT JOIN core.region r USING(region_id) LEFT JOIN core.agent a ON a.agent_id=p.current_agent_id;
CREATE OR REPLACE VIEW business.agent360 AS SELECT a.*,r.region_name,r.region_dir,COUNT(p.policy_id) policy_count,COALESCE(SUM(p.premium_amount),0) policy_premium FROM core.agent a LEFT JOIN core.region r USING(region_id) LEFT JOIN core.policy p ON p.current_agent_id=a.agent_id GROUP BY a.agent_id,a.agent_name,a.experience_years,a.joining_date,a.region_id,a.performance_rating,a.languages_known,a.specialisation,a.conversion_rate,a.median_ticket_size,a.sales_cycle_efficiency,a.first_call_dropoff_rate,a.upsell_rate,a.sla_adherence,r.region_name,r.region_dir;
